//! 🛫️ Borrowed explicit Semio native fields are measured and emitted under one ownership control.
use semio_framework_value::{ValueError,ValueRefusalKind};
use semio_framework_value::native_encoding::NativeEncodeControl;
use semio_framework_value_native_owned::native_decoding::NativeDecodeRetirementRecipient;
use store::sqlite_snapshot::{SnapshotEncoding,SqliteSnapshotControl,SqliteSnapshotPhase,SqliteDatabaseLimits,artifact::owned_workspace};
use {crate::schema::geometry::SemioTransform, crate::schema::geometry::native::{NativeF64, NativeF32}};
pub struct Writer<'a,'b,'c>{control:&'a mut NativeEncodeControl<'b>,output:Option<&'c mut Vec<u8>>,count:usize,entities:usize,limits:SqliteDatabaseLimits,primitive_value_limit:Option<usize>}
impl Writer<'_,'_,'_>{
 pub fn bytes(&mut self,bytes:&[u8])->Result<(),ValueError>{self.count=self.count.checked_add(bytes.len()).filter(|count|*count<=self.limits.max_file_bytes&&self.primitive_value_limit.is_none_or(|maximum|*count<=maximum)).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit,"Semio native output exceeds file or ownership limit"))?;for chunk in bytes.chunks(256){if let Some(output)=self.output.as_mut(){if output.len().checked_add(chunk.len()).filter(|length|*length<=output.capacity()).is_none(){return Err(ValueError::new(ValueRefusalKind::InvariantViolated,"Semio native writer exceeded admitted output"))}output.extend_from_slice(chunk)}self.control.advance(chunk.len())?;}Ok(())}
 pub fn entities(&mut self,count:usize)->Result<(),ValueError>{let next=self.entities.checked_add(count).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"Semio native output entity count overflow"))?;if next>self.limits.max_rows{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit,"Semio native output entities exceed caller row limit"))}self.entities=next;Ok(())}
 pub fn byte(&mut self,value:u8)->Result<(),ValueError>{self.bytes(&[value])}
 pub fn varint(&mut self,mut value:u64)->Result<(),ValueError>{let mut bytes=[0;10];let mut length=0;loop{bytes[length]=(value&127) as u8;value>>=7;if value!=0{bytes[length]|=128}length+=1;if value==0{break}}self.bytes(&bytes[..length])}
 pub fn string(&mut self,value:&str,encoding:SnapshotEncoding)->Result<(),ValueError>{match encoding{SnapshotEncoding::Binary=>{self.varint(u64::try_from(value.len()).map_err(|_|ValueError::new(ValueRefusalKind::WorkLimit,"Semio native text exceeds binary width"))?)?;self.bytes(value.as_bytes())},SnapshotEncoding::Text=>{const DIGITS:&[u8;16]=b"0123456789abcdef";for byte in value.bytes(){self.bytes(&[DIGITS[usize::from(byte>>4)],DIGITS[usize::from(byte&15)]])?;}Ok(())}}}
 pub fn number(&mut self,value:f64,encoding:SnapshotEncoding)->Result<(),ValueError>{if encoding==SnapshotEncoding::Binary{return self.bytes(&value.to_le_bytes())}let mut word=Word{bytes:[0;384],length:0};std::fmt::write(&mut word,format_args!("{}",NativeF64(value))).map_err(|_|ValueError::new(ValueRefusalKind::WorkLimit,"Semio native scalar exceeds stack word"))?;self.bytes(&word.bytes[..word.length])}
 pub fn number32(&mut self,value:f32,encoding:SnapshotEncoding)->Result<(),ValueError>{if encoding==SnapshotEncoding::Binary{return self.bytes(&value.to_le_bytes())}let mut word=Word{bytes:[0;384],length:0};std::fmt::write(&mut word,format_args!("{}",NativeF32(value))).map_err(|_|ValueError::new(ValueRefusalKind::WorkLimit,"Semio native binary32 scalar exceeds stack word"))?;self.bytes(&word.bytes[..word.length])}
 pub fn hex_number(&mut self,value:f64,encoding:SnapshotEncoding)->Result<(),ValueError>{if encoding==SnapshotEncoding::Binary{return self.bytes(&value.to_le_bytes())}let mut word=Word{bytes:[0;384],length:0};std::fmt::write(&mut word,format_args!("{}",NativeF64(value))).map_err(|_|ValueError::new(ValueRefusalKind::WorkLimit,"Semio native scalar exceeds stack word"))?;let text=std::str::from_utf8(&word.bytes[..word.length]).map_err(|_|ValueError::new(ValueRefusalKind::InvalidValue,"Semio numeric word is not UTF-8"))?;self.string(text,encoding)}
 pub fn integer(&mut self,value:u64,encoding:SnapshotEncoding)->Result<(),ValueError>{if encoding==SnapshotEncoding::Binary{return self.varint(value)}let mut word=Word{bytes:[0;384],length:0};std::fmt::write(&mut word,format_args!("{value}")).map_err(|_|ValueError::new(ValueRefusalKind::WorkLimit,"Semio native integer exceeds stack word"))?;self.bytes(&word.bytes[..word.length])}
 pub fn fixed_u32(&mut self,value:u32,encoding:SnapshotEncoding)->Result<(),ValueError>{if encoding==SnapshotEncoding::Binary{self.bytes(&value.to_le_bytes())}else{self.integer(u64::from(value),encoding)}}
 pub fn fixed_u64(&mut self,value:u64,encoding:SnapshotEncoding)->Result<(),ValueError>{if encoding==SnapshotEncoding::Binary{self.bytes(&value.to_le_bytes())}else{self.integer(value,encoding)}}
 pub fn signed64(&mut self,value:i64,encoding:SnapshotEncoding)->Result<(),ValueError>{if encoding==SnapshotEncoding::Binary{return self.bytes(&value.to_le_bytes())}let mut word=Word{bytes:[0;384],length:0};std::fmt::write(&mut word,format_args!("{value}")).map_err(|_|ValueError::new(ValueRefusalKind::WorkLimit,"Semio native signed integer exceeds stack word"))?;self.bytes(&word.bytes[..word.length])}
 pub fn octets(&mut self,value:&[u8],encoding:SnapshotEncoding)->Result<(),ValueError>{if encoding==SnapshotEncoding::Binary{self.varint(u64::try_from(value.len()).map_err(|_|ValueError::new(ValueRefusalKind::WorkLimit,"Semio native octet length exceeds width"))?)?;self.bytes(value)}else{const DIGITS:&[u8;16]=b"0123456789abcdef";for byte in value{self.bytes(&[DIGITS[usize::from(byte>>4)],DIGITS[usize::from(byte&15)]])?;}Ok(())}}
 pub fn binary_envelope(&mut self,token:&str)->Result<(),ValueError>{self.bytes(b"\x89SEM\r\n\x1a\n")?;self.bytes(&u32::try_from(token.len()).map_err(|_|ValueError::new(ValueRefusalKind::WorkLimit,"Semio native envelope width"))?.to_le_bytes())?;self.bytes(token.as_bytes())}
 pub fn text_record(&mut self,emit:impl Fn(&mut Writer<'_,'_,'_>)->Result<(),ValueError>)->Result<(),ValueError>{let limits=self.limits;let primitive_value_limit=self.primitive_value_limit;let size=self.control.scoped_stage(|control|{control.begin_stage(0)?;let mut measure=Writer{control,output:None,count:0,entities:0,limits,primitive_value_limit};emit(&mut measure)?;Ok::<usize,ValueError>(measure.count)})?;self.varint(u64::try_from(size).map_err(|_|ValueError::new(ValueRefusalKind::WorkLimit,"Semio text record exceeds binary width"))?)?;let start=self.count;emit(self)?;if self.count.checked_sub(start)!=Some(size){return Err(ValueError::new(ValueRefusalKind::InvariantViolated,"Semio text record measured size differs"))}Ok(())}
 pub fn delimiter(&mut self,bytes:&[u8],encoding:SnapshotEncoding)->Result<(),ValueError>{if encoding==SnapshotEncoding::Text{self.bytes(bytes)?;}Ok(())}
 pub fn list<T>(&mut self,items:&[T],encoding:SnapshotEncoding,mut emit:impl FnMut(&mut Self,&T)->Result<(),ValueError>)->Result<(),ValueError>{self.entities(items.len())?;if encoding==SnapshotEncoding::Binary{self.varint(u64::try_from(items.len()).map_err(|_|ValueError::new(ValueRefusalKind::WorkLimit,"Semio native list exceeds binary width"))?)?;}else{self.bytes(b"[")?;}for(index,item)in items.iter().enumerate(){if index!=0{self.delimiter(b",",encoding)?;}emit(self,item)?;}self.delimiter(b"]",encoding)}
 pub fn reference(&mut self,target:&semio_framework_artifact_reference::ArtifactRef,encoding:SnapshotEncoding)->Result<(),ValueError>{self.entities(1)?;self.delimiter(b"[",encoding)?;for(index,field)in [&target.artifact_id,&target.dialect.artifact_kind,&target.dialect.standard,&target.dialect.subset].into_iter().enumerate(){if index!=0{self.delimiter(b",",encoding)?;}self.string(field,encoding)?;}self.delimiter(b"]",encoding)}
 pub fn child<T>(&mut self,child:&store::os_store::artifact_child::ArtifactChild<T>,encoding:SnapshotEncoding)->Result<(),ValueError>{self.delimiter(b"[",encoding)?;self.string(&child.child_id,encoding)?;self.delimiter(b",",encoding)?;self.reference(&child.target,encoding)?;self.delimiter(b"]",encoding)}
 pub fn optional_child<T>(&mut self,child:&Option<store::os_store::artifact_child::ArtifactChild<T>>,encoding:SnapshotEncoding)->Result<(),ValueError>{if let Some(child)=child{self.entities(1)?;if encoding==SnapshotEncoding::Binary{self.byte(1)?;}self.child(child,encoding)}else if encoding==SnapshotEncoding::Binary{self.byte(0)}else{self.bytes(b"[]")}}
 pub fn transform(&mut self,transform:&SemioTransform,encoding:SnapshotEncoding)->Result<(),ValueError>{self.delimiter(b"[",encoding)?;for(index,value)in [transform.translation.x,transform.translation.y,transform.translation.z,transform.rotation.x,transform.rotation.y,transform.rotation.z,transform.rotation.w,transform.scale.x,transform.scale.y,transform.scale.z].into_iter().enumerate(){if index!=0{self.delimiter(b",",encoding)?;}self.number(value,encoding)?;}self.delimiter(b"]",encoding)}
 pub fn pin(&mut self,pin:&store::LinkPin,encoding:SnapshotEncoding)->Result<(),ValueError>{match pin{store::LinkPin::Head=>if encoding==SnapshotEncoding::Binary{self.byte(0)}else{self.bytes(b"[h]")},store::LinkPin::Checkpoint{id}=>{if encoding==SnapshotEncoding::Binary{self.byte(1)?;}else{self.bytes(b"[c,")?;}self.string(id,encoding)?;self.delimiter(b"]",encoding)},store::LinkPin::Snapshot{blob}=>{self.entities(1)?;if encoding==SnapshotEncoding::Binary{self.byte(2)?;}else{self.bytes(b"[s,")?;}self.string(&blob.hash,encoding)?;self.delimiter(b",",encoding)?;self.integer(blob.size,encoding)?;self.delimiter(b",",encoding)?;self.string(&blob.media_type,encoding)?;self.delimiter(b"]",encoding)}}}
 pub fn link(&mut self,link:&store::ArtifactLink,encoding:SnapshotEncoding)->Result<(),ValueError>{self.delimiter(b"[",encoding)?;self.reference(&link.target,encoding)?;self.delimiter(b",",encoding)?;self.pin(&link.pin,encoding)?;self.delimiter(b",",encoding)?;self.string(&link.role,encoding)?;self.delimiter(b"]",encoding)}
}
struct Word{bytes:[u8;384],length:usize}
impl std::fmt::Write for Word{fn write_str(&mut self,value:&str)->std::fmt::Result{let end=self.length.checked_add(value.len()).filter(|end|*end<=self.bytes.len()).ok_or(std::fmt::Error)?;self.bytes[self.length..end].copy_from_slice(value.as_bytes());self.length=end;Ok(())}}
/// 🎟️ Emits one measured native payload; the owner's explicit SQL admission runs before any original native work.
pub fn encode(encoding:SnapshotEncoding,text_preamble:&str,binary_token:&str,control:&mut SqliteSnapshotControl<'_>,fields:impl Fn(&mut Writer<'_,'_,'_>,SnapshotEncoding)->Result<(),ValueError>,native_owner:&mut semio_os_kernel::NativeSnapshotEncodeOwner<'_, '_>,output:&mut Option<super::native_decoding::Output<store::io::IoPayload>>)->super::native_decoding::Outcome{encode_fields(encoding,text_preamble,binary_token,control,false,|_|Ok(()),fields,native_owner,output)}
/// 🎟️ Uses the caller's physical ledger after the owner completes explicit SQL admission before the retained prefix.
pub fn encode_admitted(encoding:SnapshotEncoding,text_preamble:&str,binary_token:&str,control:&mut SqliteSnapshotControl<'_>,admit:impl FnOnce(&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>,fields:impl Fn(&mut Writer<'_,'_,'_>,SnapshotEncoding)->Result<(),ValueError>,native_owner:&mut semio_os_kernel::NativeSnapshotEncodeOwner<'_, '_>,output:&mut Option<super::native_decoding::Output<store::io::IoPayload>>)->super::native_decoding::Outcome{encode_fields(encoding,text_preamble,binary_token,control,true,admit,fields,native_owner,output)}
fn encode_fields(encoding:SnapshotEncoding,text_preamble:&str,binary_token:&str,control:&mut SqliteSnapshotControl<'_>,semantic_admitted:bool,admit:impl FnOnce(&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>,fields:impl Fn(&mut Writer<'_,'_,'_>,SnapshotEncoding)->Result<(),ValueError>,native_owner:&mut semio_os_kernel::NativeSnapshotEncodeOwner<'_, '_>,output:&mut Option<super::native_decoding::Output<store::io::IoPayload>>)->super::native_decoding::Outcome{
 use store::space_history::io::sqlite::snapshot::settlement::TypedFileSettlement;
 use store::sqlite_snapshot::SqliteStageFailure as Stage;
 use semio_framework_value::RetainedWorkOutcome;
 let limits=control.limits();let primitive_value_limit=(!semantic_admitted).then_some(limits.max_value_bytes);
 let admitted=(||->Result<(usize,usize),ValueError>{
  if output.is_some(){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"original snapshot output slot is occupied"))}
  native_owner.native().checkpoint()?;control.checkpoint(SqliteSnapshotPhase::EncodeNative,0,0)?;admit(control)?;
  let before=native_owner.native().owned_bytes();let maximum=before.checked_add(control.allocation_remaining_bytes()).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit,"native snapshot allowance overflow"))?;Ok((before,maximum))
 })();
 let(before,maximum)=match admitted{Ok(admitted)=>admitted,Err(error)=>return super::native_decoding::refused(error)};
 let settlement=TypedFileSettlement::new(control,before,SqliteSnapshotPhase::EncodeNative);
 let mut observer=|event:semio_framework_value::native_encoding::NativeEncodeProgress|settlement.observe(event.owned_bytes,event.completed,event.total);
 let turn=native_owner.scoped_native(maximum,&mut observer,|owner|owner.receive::<Vec<u8>,super::native_decoding::Output<store::io::IoPayload>,store::NativeSnapshotFailure>(output,&mut |slot,published,_marker,_unwind,native,body|{
  let before_work=native.actual_work();
  let operation=(||->Result<store::io::IoPayload,ValueError>{
   let envelope=|writer:&mut Writer<'_,'_,'_>|{if encoding==SnapshotEncoding::Text{writer.bytes(text_preamble.as_bytes())?;}else{writer.bytes(b"\x89SEM\r\n\x1a\n")?;writer.bytes(&u32::try_from(binary_token.len()).map_err(|_|ValueError::new(ValueRefusalKind::WorkLimit,"Semio native envelope width"))?.to_le_bytes())?;writer.bytes(binary_token.as_bytes())?;}fields(writer,encoding)};
   native.begin_stage(0)?;let mut measure=Writer{control:&mut *native,output:None,count:0,entities:0,limits,primitive_value_limit};envelope(&mut measure)?;let count=measure.count;
   native.begin_stage(count)?;*slot=Some(Vec::new());let prefix=slot.as_mut().ok_or_else(||ValueError::new(ValueRefusalKind::InvariantViolated,"native output prefix is absent"))?;body.allocate_encode_vec_into(native,count,prefix,1)?;
   let mut writer=Writer{control:&mut *native,output:Some(&mut *prefix),count:0,entities:0,limits,primitive_value_limit};envelope(&mut writer)?;if writer.count!=count||prefix.len()!=count{return Err(ValueError::new(ValueRefusalKind::InvariantViolated,"Semio native measured and emitted sizes differ"))}native.checkpoint()?;
   let bytes=slot.take().ok_or_else(||ValueError::new(ValueRefusalKind::InvariantViolated,"native output prefix was lost"))?;
   Ok(match encoding{SnapshotEncoding::Binary=>store::io::IoPayload::Binary(bytes),SnapshotEncoding::Text=>store::io::IoPayload::Text(String::from_utf8(bytes).map_err(|_|ValueError::new(ValueRefusalKind::InvalidValue,"Semio native output is not UTF-8"))?)})
  })().map_err(store::NativeSnapshotFailure::from);
  let settled=settlement.finish_body(native.owned_bytes());
  *published=Some(match settled{Ok(())=>operation.map_err(Stage::Operation),Err(refusal)=>Err(Stage::Settlement{operation,refusal,receipt:None})});
  RetainedWorkOutcome{result:Ok(()),work:native.actual_work().checked_sub(before_work).expect("original native work is monotone")}
 }));
 let result=match settlement.cause.borrow_mut().take(){Some(refusal)=>Err(Stage::Settlement{operation:turn.result,refusal,receipt:None}),None=>turn.result.map_err(Stage::Operation)};
 RetainedWorkOutcome{result,work:turn.work}
}
/// 🧷️ Emits a record-pack body as the binary field section of one measured native payload; the body is built under the writer's own allocation control, so its bytes are priced and cancellable before they are copied.
pub fn record_binary<S:crate::SemioRecordPack>(snapshot:&S,writer:&mut Writer<'_,'_,'_>)->Result<(),ValueError>{writer.entities(1)?;let body=snapshot.record_binary(&mut *writer.control)?;writer.bytes(&body)}
